<script setup>
import guide from '../../../API_SETUP_GUIDE.md?raw'
defineEmits(['close'])
const sections=guide.trim().split(/\n(?=## )/).map(section=>{const [heading,...lines]=section.split('\n');return {heading:heading.replace(/^#+ /,''),lines:lines.filter(line=>line.trim())}})
</script>
<template><div class="api-guide-backdrop" @click.self="$emit('close')"><section role="dialog" aria-modal="true" aria-labelledby="api-guide-title" class="api-guide" @keydown.esc="$emit('close')" tabindex="-1"><header><h2 id="api-guide-title">API 设置说明</h2><button autofocus type="button" @click="$emit('close')">关闭说明</button></header><article v-for="(section,index) in sections" :key="index"><h3>{{section.heading}}</h3><p v-for="(line,i) in section.lines" :key="i" :class="{bullet:line.startsWith('- ')}">{{line}}</p></article></section></div></template>
<style scoped>.api-guide-backdrop{position:fixed;inset:0;z-index:110;background:#0009;display:grid;place-items:center;padding:24px}.api-guide{width:min(860px,100%);max-height:90vh;overflow:auto;background:var(--panel,#202827);color:var(--text,#eef3f1);border:1px solid var(--border,#35423f);border-radius:16px;padding:0 28px 24px}.api-guide header{position:sticky;top:0;background:var(--panel,#202827);display:flex;justify-content:space-between;align-items:center;gap:15px;padding:18px 0;border-bottom:1px solid var(--border,#35423f)}.api-guide h2{margin:0;font-size:20px}.api-guide h3{font-size:16px;margin:24px 0 12px}.api-guide p{font-size:14px;line-height:1.85;overflow-wrap:anywhere}.bullet{padding-left:12px}@media(max-width:600px){.api-guide-backdrop{padding:10px}.api-guide{padding:0 16px 20px}}</style>
